CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, polaco_limit integer NOT NULL CHECK(polaco_limit>=0), logo_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid REFERENCES groups(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','owner','polaco')), name text NOT NULL, username text NOT NULL UNIQUE, password_hash text NOT NULL, preferences jsonb NOT NULL DEFAULT '{}', deleted_at timestamptz, deleted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CHECK((role='admin')=(group_id IS NULL)));
CREATE UNIQUE INDEX one_owner ON users(group_id) WHERE role='owner';
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', price bigint NOT NULL CHECK(price>0), available integer NOT NULL CHECK(available>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0), assigned integer NOT NULL DEFAULT 0 CHECK(assigned>=0), image_id uuid, deleted_at timestamptz, deleted_by uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', photo_id uuid, deleted_at timestamptz, deleted_by uuid, deleted_batch uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, client_id uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id) ON DELETE SET NULL, product_name text NOT NULL, original_price bigint NOT NULL, unit_price bigint NOT NULL CHECK(unit_price>0), quantity integer NOT NULL CHECK(quantity>0), status text NOT NULL CHECK(status IN ('pending','decision','active','paid','cancelled')), plan jsonb NOT NULL, schedule jsonb NOT NULL, version integer NOT NULL DEFAULT 1, had_assignment boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id) ON DELETE SET NULL, idempotency_key text NOT NULL, deleted_at timestamptz, deleted_by uuid, deleted_batch uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by,idempotency_key));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, amount bigint NOT NULL CHECK(amount>0), kind text NOT NULL CHECK(kind IN ('installment','capital')), targets jsonb NOT NULL DEFAULT '[]', paid_on date NOT NULL, note text NOT NULL DEFAULT '', voided boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id) ON DELETE SET NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by,idempotency_key));
CREATE TABLE price_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, requester_id uuid REFERENCES users(id) ON DELETE SET NULL, version integer NOT NULL, price bigint NOT NULL CHECK(price>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')), reason text NOT NULL DEFAULT '', decided_by uuid REFERENCES users(id) ON DELETE SET NULL, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(purchase_id,version));
CREATE TABLE inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id) ON DELETE CASCADE, purchase_id uuid REFERENCES purchases(id) ON DELETE SET NULL, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, quantity integer NOT NULL, kind text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE access_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, requester_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, permission text NOT NULL CHECK(permission IN ('read','edit')), scope text NOT NULL, all_clients boolean NOT NULL DEFAULT false, client_ids jsonb NOT NULL DEFAULT '[]', purchase_ids jsonb NOT NULL DEFAULT '[]', expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid REFERENCES groups(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('direct','group','support')), name text NOT NULL, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members (conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT '1970-01-01', PRIMARY KEY(conversation_id,user_id));
CREATE TABLE files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid REFERENCES groups(id) ON DELETE CASCADE, uploader_id uuid REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760), data bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, body text NOT NULL DEFAULT '', file_id uuid REFERENCES files(id) ON DELETE SET NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(sender_id,idempotency_key));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL DEFAULT '', path text NOT NULL, subject_id uuid, dedupe text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,dedupe));
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid REFERENCES groups(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX clients_owner ON clients(group_id,owner_id);
CREATE INDEX purchases_client ON purchases(client_id);
CREATE INDEX payments_purchase ON payments(purchase_id,created_at);
CREATE INDEX grants_requester ON access_grants(requester_id,status,expires_at);
CREATE INDEX messages_conversation ON messages(conversation_id,created_at);
CREATE INDEX notifications_user ON notifications(user_id,created_at);
CREATE INDEX audit_entity ON audit(entity_id,created_at);
